import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { webcrypto, createHash } from 'node:crypto';
import {
  compileAssetRevision,
  assetRevisionMime,
  loadPreviewArtwork,
  loadVerifiedArtwork,
  verifiedArtworkBlob,
  verifiedPreviewBackground,
} from '../content-design/assets.mjs';
import { HORIZON_ART_CANDIDATES } from '../content-design/horizon-art.mjs';
import { CONTENT_ARTWORK_LOAD_TIMEOUT_MS } from '../content-design/limits.mjs';
import { createOpeningCandidates } from '../content-design/horizon-candidates.mjs';
import { compileContentProject, resolveMission } from '../content-design/project.mjs';
import { prepareContentPreview } from '../content-design/preview.mjs';
import { canonicalJSON, dataIdentity } from '../data-json.mjs';
import { acquireCandidatePicture } from '../content-design/picture.mjs';
import { rasterFixtures } from './helpers/raster-fixtures.mjs';
import { waitFor } from './helpers/wait-for.mjs';
const asset = HORIZON_ART_CANDIDATES[0];
const bytes = await readFile(new URL(`../${asset.path}`, import.meta.url));
const fetchAsset = async () => new Response(bytes);
const digest = (value) => webcrypto.subtle.digest('SHA-256', value);

test('native artwork encoding follows verification and cancellation retires its reader', async (t) => {
  const descriptor = Object.getOwnPropertyDescriptor(globalThis, 'FileReader');
  let reader;
  class NativeReader {
    constructor() {
      reader = this;
      this.aborted = false;
    }
    readAsDataURL(blob) {
      this.blob = blob;
    }
    abort() {
      this.aborted = true;
      this.onabort?.();
    }
  }
  Object.defineProperty(globalThis, 'FileReader', { configurable: true, value: NativeReader });
  t.after(() =>
    descriptor
      ? Object.defineProperty(globalThis, 'FileReader', descriptor)
      : delete globalThis.FileReader,
  );
  const originalBtoa = Object.getOwnPropertyDescriptor(globalThis, 'btoa');
  Object.defineProperty(globalThis, 'btoa', {
    configurable: true,
    value: () => assert.fail('Native encoding needs no JS binary string.'),
  });
  t.after(() => Object.defineProperty(globalThis, 'btoa', originalBtoa));
  const loading = loadPreviewArtwork(asset, { fetchAsset, digest });
  await waitFor(() => reader?.blob, { message: 'Native encoding begins after validation' });
  assert.deepEqual(new Uint8Array(await reader.blob.arrayBuffer()), new Uint8Array(bytes));
  assert.equal(reader.blob.type, assetRevisionMime(asset));
  reader.result = `data:image/png;base64,${bytes.toString('base64')}`;
  reader.onload();
  assert.equal((await loading).dataUrl, reader.result);
  const controller = new AbortController();
  reader = null;
  const cancelled = loadPreviewArtwork(asset, { fetchAsset, digest, signal: controller.signal });
  await waitFor(() => reader?.blob, { message: 'Cancellable native encoding begins' });
  controller.abort();
  await assert.rejects(cancelled, { name: 'AbortError' });
  assert.equal(reader.aborted, true);
  assert.equal(reader.onload, null);
  reader = null;
  await assert.rejects(
    loadPreviewArtwork({ ...asset, width: asset.width + 1 }, { fetchAsset, digest }),
    /dimensions/,
  );
  assert.equal(reader, null, 'Bad bytes/header never enter native encoding.');
});

test('PNG, JPEG and WebP asset pins retain exact bytes, MIME and gameplay-independent identities', async () => {
  for (const { extension, mime, bytes: original } of rasterFixtures()) {
    const pin = {
      ...asset,
      path: `content-design/assets/fixture/compact.${extension}`,
      sha256: createHash('sha256').update(original).digest('hex'),
      bytes: original.length,
      width: 1,
      height: 1,
    };
    assert.equal(canonicalJSON(compileAssetRevision(pin)), canonicalJSON(pin));
    assert.equal(dataIdentity(compileAssetRevision(pin)), dataIdentity(pin));
    assert.equal(assetRevisionMime(pin), mime);
    if (extension === 'jpg')
      assert.equal(assetRevisionMime({ ...pin, path: pin.path.replace('.jpg', '.jpeg') }), mime);
    const loadArtwork = (value) =>
      loadPreviewArtwork(value, { fetchAsset: async () => new Response(original), digest });
    const media = await loadArtwork(pin);
    assert.equal(media.dataUrl, `data:${mime};base64,${original.toString('base64')}`);
    assert.equal(verifiedPreviewBackground(pin, media).dataUrl, media.dataUrl);
    let closed = 0;
    const picture = await acquireCandidatePicture(pin, {
      loadArtwork,
      decodeImage: async (url) => {
        assert.equal(url, media.dataUrl);
        return { width: 1, height: 1, close: () => closed++ };
      },
    });
    assert.equal(picture.officialProgressEligible, false);
    picture.release();
    assert.equal(closed, 1);
    await assert.rejects(
      acquireCandidatePicture(pin, {
        loadArtwork,
        decodeImage: async () => {
          throw new Error('Complete decoding failed');
        },
      }),
      /Complete decoding failed/,
    );
    await assert.rejects(
      loadArtwork({
        ...pin,
        path: `content-design/assets/fixture/wrong.${extension === 'png' ? 'webp' : 'png'}`,
      }),
      /raster header/,
    );
  }
  assert.equal(canonicalJSON(compileAssetRevision(asset)), canonicalJSON(asset));
});

test('every authored picture has unique original bytes and leaves every mission rule unchanged', async () => {
  const grey = compileContentProject(createOpeningCandidates());
  const artSource = createOpeningCandidates({ artwork: true });
  const art = compileContentProject(artSource);
  const seen = new Set();
  assert.equal(HORIZON_ART_CANDIDATES.length, 10);
  assert.equal(artSource.missions.length, HORIZON_ART_CANDIDATES.length);
  assert(artSource.missions.every((mission) => mission.presentation.backgroundAssetId));
  for (const candidate of HORIZON_ART_CANDIDATES) {
    const original = await readFile(new URL(`../${candidate.path}`, import.meta.url));
    assert.equal(original.length, candidate.bytes, candidate.id);
    assert.equal(createHash('sha256').update(original).digest('hex'), candidate.sha256);
    assert.equal(original.readUInt32BE(16), candidate.width);
    assert.equal(original.readUInt32BE(20), candidate.height);
    assert.equal(candidate.width, candidate.height * 2);
    assert(!seen.has(candidate.sha256), 'Each mission needs its own composition.');
    seen.add(candidate.sha256);
    const consumers = artSource.missions.filter(
      (mission) => mission.presentation.backgroundAssetId === candidate.id,
    );
    assert.equal(consumers.length, 1, candidate.id);
    const media = await loadPreviewArtwork(candidate, {
      fetchAsset: async () => new Response(original),
      digest,
    });
    assert.equal(verifiedPreviewBackground(candidate, media).name, candidate.alt);
  }
  for (const mission of artSource.missions) {
    assert.equal(
      resolveMission(grey, mission.id).simulationIdentity,
      resolveMission(art, mission.id).simulationIdentity,
      mission.id,
    );
  }
});

test('original candidate image is pinned and artwork cannot change simulation identity', async () => {
  assert.equal(bytes.length, asset.bytes);
  assert.equal(createHash('sha256').update(bytes).digest('hex'), asset.sha256);
  assert.equal(bytes.readUInt32BE(16), asset.width);
  assert.equal(bytes.readUInt32BE(20), asset.height);
  const grey = compileContentProject(createOpeningCandidates());
  const artSource = createOpeningCandidates({ artwork: true });
  const art = compileContentProject(artSource);
  assert.equal(
    resolveMission(grey, 'first-return').simulationIdentity,
    resolveMission(art, 'first-return').simulationIdentity,
  );
  const media = await loadPreviewArtwork(asset, { fetchAsset, digest });
  const theme = JSON.parse(
    await readFile(new URL('../content-design/themes.json', import.meta.url)),
  ).themes.find((t) => t.id === 'horizon');
  const preview = prepareContentPreview(artSource, 'first-return', { theme, artwork: media });
  assert.equal(preview.scenario.visualOverrides.background.dataUrl, media.dataUrl);
  assert.equal(preview.manifest.background.sha256, asset.sha256);
  assert.equal(preview.manifest.officialProgressEligible, false);
  assert(
    preview.manifest.diagnostics.some((d) => d.code === 'candidate-art-not-visually-qualified'),
  );
  assert.throws(() => prepareContentPreview(artSource, 'first-return', { theme }), /verify/);
  assert.throws(() => verifiedPreviewBackground({ ...asset, revision: 'r2' }, media), /verify/);
  assert.throws(() => verifiedPreviewBackground(asset, { ...media }), /verify/);
});

test('unresolved, hostile and external asset references are rejected before any fetch', () => {
  const project = createOpeningCandidates();
  project.missions[0].presentation.backgroundAssetId = 'missing';
  assert.throws(() => compileContentProject(project), /Missing pinned/);
  for (const path of [
    'https://example.com/a.png',
    '/content-design/assets/a.png',
    'content-design/assets/../a.png',
    'content-design/assets//a.png',
    'content-design/assets/a.svg',
    'content-design/assets/a.png?x',
  ])
    assert.throws(() => compileAssetRevision({ ...asset, path }));
  assert.throws(() => compileAssetRevision({ ...asset, sha256: [asset.sha256] }));
  assert.throws(() => compileAssetRevision({ ...asset, review: 'approved' }));
  assert.throws(() => compileAssetRevision({ ...asset, bytes: 5 * 1024 * 1024 }));
});

test('artwork rejects changed bytes, length, dimensions and redirects', async () => {
  await assert.rejects(
    loadPreviewArtwork({ ...asset, sha256: '0'.repeat(64) }, { fetchAsset, digest }),
    /digest/,
  );
  await assert.rejects(
    loadPreviewArtwork({ ...asset, bytes: bytes.length - 1 }, { fetchAsset, digest }),
    /length/,
  );
  await assert.rejects(
    loadPreviewArtwork({ ...asset, bytes: bytes.length + 1 }, { fetchAsset, digest }),
    /length/,
  );
  await assert.rejects(
    loadPreviewArtwork({ ...asset, width: asset.width + 1 }, { fetchAsset, digest }),
    /dimensions/,
  );
  await assert.rejects(
    loadPreviewArtwork(asset, { fetchAsset: async () => ({ ok: true, redirected: true }) }),
    /redirection/,
  );
});

test('stalled artwork transport is bounded and closure cancels even an uncooperative fetch', async () => {
  await assert.rejects(
    loadPreviewArtwork(asset, { fetchAsset: () => new Promise(() => {}), timeoutMs: 5 }),
    /in time/,
  );
  const controller = new AbortController();
  const loading = loadPreviewArtwork(asset, {
    fetchAsset: () => new Promise(() => {}),
    signal: controller.signal,
  });
  controller.abort();
  await assert.rejects(loading, { name: 'AbortError' });
});

test('reviewed originals have a bounded slow-device verification budget beyond the legacy deadline', async () => {
  const media = await loadPreviewArtwork(asset, {
    fetchAsset,
    digest,
    timeoutMs: 20001,
  });
  assert.equal(verifiedPreviewBackground(asset, media).name, asset.alt);
  await assert.rejects(
    loadPreviewArtwork(asset, {
      fetchAsset: () => assert.fail('An invalid deadline must reject before fetching'),
      timeoutMs: CONTENT_ARTWORK_LOAD_TIMEOUT_MS + 1,
    }),
    /timeout/,
  );
});

test('binary artwork retains verified original bytes without preview encoding or a serializable background', async (t) => {
  const originals = ['FileReader', 'btoa'].map((name) => [
    name,
    Object.getOwnPropertyDescriptor(globalThis, name),
  ]);
  for (const [name] of originals)
    Object.defineProperty(globalThis, name, {
      configurable: true,
      value: function () {
        assert.fail('Runtime artwork must not encode a data URL.');
      },
    });
  t.after(() => {
    for (const [name, descriptor] of originals)
      if (descriptor) Object.defineProperty(globalThis, name, descriptor);
      else delete globalThis[name];
  });
  for (const { extension, mime, bytes: original } of rasterFixtures()) {
    const pin = {
      ...asset,
      path: 'content-design/assets/fixture/binary.' + extension,
      sha256: createHash('sha256').update(original).digest('hex'),
      bytes: original.length,
      width: 1,
      height: 1,
    };
    const media = await loadVerifiedArtwork(pin, {
      fetchAsset: async () => new Response(original),
      digest,
    });
    assert(Object.isFrozen(media));
    assert.equal(media.dataUrl, undefined);
    const blob = verifiedArtworkBlob(pin, media);
    assert.equal(blob, media.blob);
    assert.equal(blob.type, mime);
    assert.equal(blob.size, original.length);
    assert.deepEqual(new Uint8Array(await blob.arrayBuffer()), new Uint8Array(original));
    assert.throws(() => verifiedArtworkBlob(pin, { ...media }), /verify/);
    assert.throws(() => verifiedArtworkBlob({ ...pin, revision: 'other' }, media), /verify/);
    assert.throws(() => verifiedPreviewBackground(pin, media), /verify/);
  }
});

test('binary artwork keeps exact length, digest, raster, dimensions and redirect rejection', async () => {
  for (const [pin, expected] of [
    [{ ...asset, sha256: '0'.repeat(64) }, /digest/],
    [{ ...asset, bytes: bytes.length - 1 }, /length/],
    [{ ...asset, bytes: bytes.length + 1 }, /length/],
    [{ ...asset, width: asset.width + 1 }, /dimensions/],
    [{ ...asset, path: 'content-design/assets/fixture/wrong.webp' }, /raster header/],
  ])
    await assert.rejects(loadVerifiedArtwork(pin, { fetchAsset, digest }), expected);
  await assert.rejects(
    loadVerifiedArtwork(asset, { fetchAsset: async () => ({ ok: true, redirected: true }) }),
    /redirection/,
  );
  await assert.rejects(
    loadVerifiedArtwork(asset, {
      fetchAsset: () => assert.fail('Invalid deadlines cannot admit a fetch.'),
      timeoutMs: CONTENT_ARTWORK_LOAD_TIMEOUT_MS + 1,
    }),
    /timeout/,
  );
});

test('binary artwork cancellation settles while an admitted digest is still held', async () => {
  let entered = false,
    finishDigest;
  const controller = new AbortController();
  const loading = loadVerifiedArtwork(asset, {
    fetchAsset,
    signal: controller.signal,
    digest: (value) => {
      assert.deepEqual(value, new Uint8Array(bytes));
      entered = true;
      return new Promise((resolve) => {
        finishDigest = resolve;
      });
    },
  });
  const rejected = assert.rejects(loading, { name: 'AbortError' });
  await waitFor(() => entered, { message: 'The exact binary digest must be admitted first.' });
  controller.abort();
  await rejected;
  finishDigest(await digest(bytes));
  await new Promise((resolve) => setImmediate(resolve));
  await assert.rejects(loading, { name: 'AbortError' });
});

