function ownedURLFixture(t) {
  const urls = [],
    revoked = [];
  const api = {
    createObjectURL(blob) {
      assert.equal(blob, binaryMedia.blob);
      const url = URL.createObjectURL(blob);
      urls.push(url);
      return url;
    },
    revokeObjectURL(url) {
      revoked.push(url);
      URL.revokeObjectURL(url);
    },
  };
  t.after(() => {
